"""``--cross-check``: a seeded sample of candidates regenerated by a second model (T4.2 S6).

The second model is a GitHub Models model of another family than the datagen model and never
``qwen`` or ``gemma`` (ADR-0019). Both candidates are kept side by side for the human review
(T4.7b); nothing here changes a candidate. Only public text is sent (same guard as generation).
"""

from collections.abc import Mapping, Sequence

import numpy as np
from pydantic import BaseModel, ConfigDict

from pruefstand.core.errors import ConfigError
from pruefstand.core.models.corpus import Chunk
from pruefstand.core.models.dataset import QACandidate
from pruefstand.dataset.datagen_guard import check_datagen_model
from pruefstand.dataset.generate import GenStats, run_units
from pruefstand.dataset.generate_units import parse_prompt_version, unit_for_candidate
from pruefstand.llm.client import LLMClient


class CrossCheckRow(BaseModel):
    """One line of ``cross_check.jsonl``: the primary candidate and the second model's one."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    primary: QACandidate
    second: QACandidate | None
    primary_model: str
    second_model: str


def pick_sample(n: int, fraction: float, rng: np.random.Generator) -> list[int]:
    """Return the sorted indices of a seeded sample of ``fraction`` of ``n`` items (at least one).

    Examples:
        >>> sample = pick_sample(30, 0.1, np.random.default_rng(7))
        >>> len(sample), sample == sorted(set(sample))
        (3, True)
    """
    if n <= 0 or fraction <= 0:
        return []
    count = min(n, max(1, round(n * fraction)))
    return sorted(int(i) for i in rng.choice(n, size=count, replace=False))


def row_key(c: QACandidate) -> str:
    """Return the key under which a cross-check row of ``c`` is stored and reused."""
    return f"{c.prompt_version}|{c.chunk_id}|{c.question}"


def check_second_model(model: str, primary_model: str) -> None:
    """Raise ``ConfigError`` unless ``model`` is an allowed datagen model of another family."""
    second, first = check_datagen_model(model), check_datagen_model(primary_model)
    if second == first:
        msg = f"cross-check model {model} has the same family '{second}' as {primary_model}"
        raise ConfigError(msg)


class CrossCheckPlan(BaseModel):
    """Which models and which share of the candidates a cross-check covers."""

    model_config = ConfigDict(frozen=True, extra="forbid")

    model: str
    primary_model: str
    fraction: float


async def cross_check(
    cands: Sequence[QACandidate],
    chunks: Mapping[str, Chunk],
    llm: LLMClient,
    plan: CrossCheckPlan,
    rng: np.random.Generator,
    *,
    stats: GenStats | None = None,
    done: Mapping[str, CrossCheckRow] | None = None,
) -> list[CrossCheckRow]:
    """Regenerate a seeded share of ``cands`` with a second model.

    Args:
        cands: The primary candidates.
        chunks: Their source chunks by ``chunk_id``.
        llm: Client for the second model (GitHub Models, ``datagen_policy``).
        plan: The second model (family differs from the primary one), the model that wrote
            ``cands`` and the share to re-generate (0.1 = 10 %).
        rng: Seeded generator (sample and request seeds).
        stats: Receives ``cross_checked`` and the counters of the requests.
        done: Rows of an earlier run by ``row_key``; they are reused without a request.

    Returns:
        One row per sampled candidate, in input order; ``second`` is None when the second model's
        answer was refused, invalid or stopped by a quota.

    Raises:
        ConfigError: The models are not allowed or have the same family.
    """
    model, primary_model = plan.model, plan.primary_model
    check_second_model(model, primary_model)
    counts = stats if stats is not None else GenStats()
    rows: list[CrossCheckRow] = []
    for index in pick_sample(len(cands), plan.fraction, rng):
        cand = cands[index]
        seed = int(rng.integers(0, 2**31 - 1))
        if not {cand.chunk_id, *cand.extra_chunk_ids} <= chunks.keys():
            counts.add("cross_check_chunk_missing")
            continue
        if done and row_key(cand) in done:
            rows.append(done[row_key(cand)])
            counts.add("cross_checked")
            continue
        unit = unit_for_candidate(cand, dict(chunks), model, seed)
        spec = parse_prompt_version(cand.prompt_version)
        (second,) = await run_units(spec, [unit], llm, model, counts)
        rows.append(
            CrossCheckRow(
                primary=cand, second=second, primary_model=primary_model, second_model=model
            )
        )
        counts.add("cross_checked")
    return rows
